module tb_qwen2_rope_q1024_model;
 localparam integer RECORDS=6188,BASE=4096;logic clk=0,rst_n=0,start;always #0.5 clk=~clk;logic[127:0]commands[0:1],records[0:RECORDS-1];logic dqv,dqr,dsv,dsr,av,ar,asv,asr,rv,rr,rsv,rsr,wv,wr,done;logic[23:0]dqi;logic[127:0]dsd;logic[1:0]ak;logic[63:0]as,ad;logic[31:0]ab,an,ass,ads;logic[14:0]ra,wa;logic[511:0]rd,wd;logic[63:0]be;logic[7:0]status;logic[17:0]elements;logic[31:0]values,steps,lfsr;logic[63:0]dr,dw;logic dpending,apending,lpending;logic[127:0]dpending_data;logic[511:0]lpending_data,l2[0:20479],inputv[0:49151],positions[0:63],qexpected[0:49151],kexpected[0:8191];integer output_fd;integer projection,columns,beats,fetches,dmas,delay,stores;
