 assign dqr=!dpending;assign dsv=dpending;assign dsd=dpending_data;assign ar=!apending;assign asv=apending&&delay==0;assign rr=!lpending&&(lfsr[0]||lfsr[4]);assign rsv=lpending;assign rd=lpending_data;assign wr=lfsr[1]||lfsr[7];always@(posedge clk or negedge rst_n)if(!rst_n)begin lfsr<=32'h70641024;dpending<=0;apending<=0;lpending<=0;fetches<=0;dmas<=0;delay<=0;stores<=0;end else begin lfsr<={lfsr[30:0],lfsr[31]^lfsr[21]^lfsr[1]^lfsr[0]};if(dqv&&dqr)begin dpending<=1;dpending_data<=records[dqi-BASE];fetches<=fetches+1;end if(dsv&&dsr)dpending<=0;if(rv&&rr)begin lpending<=1;lpending_data<=l2[ra];end if(rsv&&rsr)lpending<=0;if(wv&&wr)l2[wa]<=wd;if(av&&ar)begin apending<=1;delay<=lfsr[12+:2];dmas<=dmas+1;case(ak)1:for(integer i=0;i<beats;i++)l2[16384+i]=inputv[dut.batch_q*beats+i];0:l2[17408]=positions[dut.batch_q];3:begin for(integer i=0;i<beats;i++)if(l2[18432+i]!==((projection==0)?qexpected[dut.batch_q*beats+i]:kexpected[dut.batch_q*beats+i]))$fatal(1,"batch=%0d beat=%0d",dut.batch_q,i);for(integer i=0;i<beats;i++)$fdisplay(output_fd,"%0128h",l2[18432+i]);stores<=stores+1;end default:$fatal(1,"kind");endcase end if(apending)begin if(delay!=0)delay<=delay-1;else if(asv&&asr)apending<=0;end end
